import{_ as i,I as s,c as n,o as t,a5 as a,b as l,w as o,a as c,J as d,a6 as p,a7 as m,a8 as u,a9 as y,aa as g}from"./chunks/framework.BmNIwhaK.js";const _=JSON.parse('{"title":"Zero-Mock Enterprise Quality Harness and Verification Protocol","description":"Specification for the strict Zero-Mock mandate, RFC 7807 standardized error handling, 4-Cycle quality verification, and automated audit scripts applied across SyncSeries core agents and shared modules","frontmatter":{"title":"Zero-Mock Enterprise Quality Harness and Verification Protocol","sidebarTitle":"Zero-Mock Quality Harness","description":"Specification for the strict Zero-Mock mandate, RFC 7807 standardized error handling, 4-Cycle quality verification, and automated audit scripts applied across SyncSeries core agents and shared modules","head":[["meta",{"name":"keywords","content":"Zero-Mock, 4-Cycle Quality Verification, RFC 7807, Problem Details, verify-zero-mock, Automated Audit, Anti-Fake Normalcy"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/ecosystem/zero-mock-harness"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/ecosystem/zero-mock-harness"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/ecosystem/zero-mock-harness"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/ecosystem/zero-mock-harness"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/ecosystem/zero-mock-harness"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Zero-Mock Enterprise Quality Harness and Verification Protocol | Empasy Docs"}],["meta",{"property":"og:description","content":"Specification for the strict Zero-Mock mandate, RFC 7807 standardized error handling, 4-Cycle quality verification, and automated audit scripts applied across SyncSeries core agents and shared modules"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/ecosystem/zero-mock-harness"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Zero-Mock Enterprise Quality Harness and Verification Protocol | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Specification for the strict Zero-Mock mandate, RFC 7807 standardized error handling, 4-Cycle quality verification, and automated audit scripts applied across SyncSeries core agents and shared modules"}]],"sort":35},"headers":[],"relativePath":"en/ecosystem/zero-mock-harness.md","filePath":"en/ecosystem/zero-mock-harness.md","lastUpdated":1795293539000}'),f={name:"en/ecosystem/zero-mock-harness.md"};function h(k,e,S,b,x,P){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="zero-mock-enterprise-quality-harness-and-verification-protocol" tabindex="-1">Zero-Mock Enterprise Quality Harness and Verification Protocol <a class="header-anchor" href="#zero-mock-enterprise-quality-harness-and-verification-protocol" aria-label="Permalink to “Zero-Mock Enterprise Quality Harness and Verification Protocol”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Practical Implementation Example</p><p>For guidance on writing real Spring Boot and PostgreSQL tests using Testcontainers, see the <a href="/en/sdk/zero-mock-testing">Real-Environment Testing Guide</a>.</p></div><p>To ensure commercial-grade reliability, SyncSeries strictly enforces the <strong>Zero-Mock Principle</strong> and the <strong>4-Cycle Quality Verification Protocol</strong>, rejecting hardcoded fake responses in favor of verification against live databases and real network integrations.</p><hr><h2 id="_1-three-core-principles-of-zero-mock-and-commercial-quality" tabindex="-1">1. Three Core Principles of Zero-Mock and Commercial Quality <a class="header-anchor" href="#_1-three-core-principles-of-zero-mock-and-commercial-quality" aria-label="Permalink to “1. Three Core Principles of Zero-Mock and Commercial Quality”">​</a></h2>',5)),(t(),l(p,null,{default:o(()=>[d(r,{id:"mermaid-15",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%223%20Core%20Zero-Mock%20Principles%22%5D%20--%3E%20B%5B%221.%20Anti-Mock%20%26%20Full%20UI%20Spec%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%222.%20Zero%20Fake%20Normalcy%22%5D%0A%20%20%20%20A%20--%3E%20D%5B%223.%20Empirical%20Verification%22%5D%0A%0A%20%20%20%20B%20-.-%3E%20B1%5B%22No%20hardcoded%20mock%20data%3B%20materialized%20UI%20with%2030%2B%20lines%22%5D%0A%20%20%20%20C%20-.-%3E%20C1%5B%22No%20failure%20masking%3B%20RFC%207807%20standard%20error%20propagation%22%5D%0A%20%20%20%20D%20-.-%3E%20D1%5B%22Prove%20with%20live%20execution%20logs%20beyond%20mere%20compilation%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="_1-1-anti-mock-full-ui-spec-mandate" tabindex="-1">1.1 Anti-Mock &amp; Full UI Spec Mandate <a class="header-anchor" href="#_1-1-anti-mock-full-ui-spec-mandate" aria-label="Permalink to “1.1 Anti-Mock &amp; Full UI Spec Mandate”">​</a></h3><ul><li>Outside of explicit unit test isolation, writing hardcoded mock objects, dummy wrappers, or empty-return methods in production backend or frontend logic is strictly prohibited.</li><li>All REST APIs and frontend components must integrate 100% with real database queries and service interfaces.</li><li>Every UI view component must implement at least 30 lines of materialized UI elements (tables, forms, filters, etc.); empty shells or placeholder text are forbidden.</li></ul><h3 id="_1-2-zero-fake-normalcy" tabindex="-1">1.2 Zero Fake Normalcy <a class="header-anchor" href="#_1-2-zero-fake-normalcy" aria-label="Permalink to “1.2 Zero Fake Normalcy”">​</a></h3><ul><li>Suppressing exceptions in <code>catch</code> blocks or returning fabricated success statuses (<code>status: SUCCESS</code>) to mask network failures, HTTP call errors, or database query faults as normal behavior is strictly blocked.</li><li>All exceptions must be propagated to clients and upstream control systems with accurate HTTP status codes and structured diagnostic fields following the RFC 7807 Problem Details standard.</li></ul><h3 id="_1-3-empirical-verification" tabindex="-1">1.3 Empirical Verification <a class="header-anchor" href="#_1-3-empirical-verification" aria-label="Permalink to “1.3 Empirical Verification”">​</a></h3><ul><li>Rather than stopping at source code edits or clean compilation, engineers and agents must empirically verify changes by printing live database execution logs, REST API response payloads, and frontend build outputs to the console.</li></ul><hr><h2 id="_2-4-cycle-quality-verification-protocol" tabindex="-1">2. 4-Cycle Quality Verification Protocol <a class="header-anchor" href="#_2-4-cycle-quality-verification-protocol" aria-label="Permalink to “2. 4-Cycle Quality Verification Protocol”">​</a></h2><p>After any code change, build integrity is confirmed by iterating through the following four-stage regression verification process.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Verification Stage</th><th style="text-align:left;">Key Verification Items</th><th style="text-align:left;">Tools &amp; Commands</th><th style="text-align:left;">Acceptance Criteria</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>[Cycle 1] Full Build &amp; Initial Check</strong></td><td style="text-align:left;">Enterprise-wide module compilation and type checks</td><td style="text-align:left;"><code>mvn compile</code>, <code>pnpm build</code></td><td style="text-align:left;">Full build succeeds (<code>BUILD SUCCESS</code>)</td></tr><tr><td style="text-align:left;"><strong>[Cycle 2] Fixes &amp; Secondary Cross-Check</strong></td><td style="text-align:left;">Interface and type consistency verification</td><td style="text-align:left;"><code>mvn test-compile</code></td><td style="text-align:left;">Zero inter-module dependency or type errors</td></tr><tr><td style="text-align:left;"><strong>[Cycle 3] Regression Tests &amp; Tertiary Audit</strong></td><td style="text-align:left;">Unit/integration tests and static quality audit</td><td style="text-align:left;"><code>mvn test</code>, <code>verify-zero-mock.ps1</code></td><td style="text-align:left;">Unit tests pass, zero Mock violations</td></tr><tr><td style="text-align:left;"><strong>[Cycle 4] Final Regression Build &amp; Audit</strong></td><td style="text-align:left;">Clean build and independent QA cross-audit</td><td style="text-align:left;">Subagent Audit (<code>QA_Auditor</code>)</td><td style="text-align:left;">Final approval verdict (<code>APPROVED</code>)</td></tr></tbody></table><hr><h2 id="_3-enterprise-automated-audit-script-suite" tabindex="-1">3. Enterprise Automated Audit Script Suite <a class="header-anchor" href="#_3-enterprise-automated-audit-script-suite" aria-label="Permalink to “3. Enterprise Automated Audit Script Suite”">​</a></h2><p>To verify the integrity of development deliverables, SyncSeries operates three dedicated automated audit scripts across all core agents and shared modules.</p><ul><li><strong><code>verify-zero-mock.ps1</code></strong>: <ul><li>Performs static pattern analysis across Java, Vue, and TypeScript source files to detect hardcoded mock variables, arbitrary dummy collection returns, and fake branching logic.</li></ul></li><li><strong><code>verify-security-leaks.ps1</code></strong>: <ul><li>Scans all source code and configuration files (10,000+ files) for plaintext hardcoded API keys, passwords, and private authentication tokens.</li></ul></li><li><strong><code>verify-api-contracts.ps1</code></strong>: <ul><li>Audits 1:1 consistency of URLs, HTTP methods, and parameters between backend controller endpoints and frontend API client definitions.</li></ul></li></ul><hr><h2 id="_4-enterprise-1-045-test-cases-tc-and-playwright-e2e-ui-verification-status-100-passed" tabindex="-1">4. Enterprise 1,045 Test Cases (TC) and Playwright E2E UI Verification Status (100% PASSED) <a class="header-anchor" href="#_4-enterprise-1-045-test-cases-tc-and-playwright-e2e-ui-verification-status-100-passed" aria-label="Permalink to “4. Enterprise 1,045 Test Cases (TC) and Playwright E2E UI Verification Status (100% PASSED)”">​</a></h2><p>SyncSeries continuously executes a total of <strong>1,045 test cases (<code>L1</code>–<code>L5</code>)</strong> across the entire product suite (13 parts, 209 usage scenarios × 5 dimensions: <code>HAPPY_PATH</code>, <code>VALIDATION</code>, <code>BOUNDARY</code>, <code>STATE</code>, <code>PERMISSION</code>), alongside Playwright headless-browser high-resolution (<code>1920×1080</code>) screen rendering and callout annotation checks.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Verification Item</th><th style="text-align:left;">Target Scope</th><th style="text-align:left;">Pass Rate / Result</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Full Functional Test Cases (<code>L1</code>–<code>L5</code>)</strong></td><td style="text-align:left;">13 parts · 209 scenarios · 1,045 TCs</td><td style="text-align:left;"><strong><code>1,045 / 1,045 PASSED (100.0%)</code></strong></td></tr><tr><td style="text-align:left;"><strong>DB 6-Stage Standard Scripts (<code>00</code>–<code>05_*.sql</code>)</strong></td><td style="text-align:left;">9 core agent DBs (54 SQL files total)</td><td style="text-align:left;"><strong><code>0</code> violations (0 <code>ON CONFLICT</code>, 0 <code>migrations/</code>)</strong></td></tr><tr><td style="text-align:left;"><strong>Zero-Mock Static Quality Audit</strong></td><td style="text-align:left;">18 projects and microservice modules</td><td style="text-align:left;"><strong><code>18 / 18 PASSED (0 Violations)</code></strong></td></tr><tr><td style="text-align:left;"><strong>API Contract &amp; Secret Leak Audit</strong></td><td style="text-align:left;">Enterprise Canonical URLs (<code>/api/v1/{product}/...</code>) &amp; secret scan</td><td style="text-align:left;"><strong><code>11 / 11 PASSED (0 Leaks)</code></strong></td></tr><tr><td style="text-align:left;"><strong>Playwright E2E UI &amp; High-Res Capture</strong></td><td style="text-align:left;">42 raw <code>1920×1080</code> screens + 40 callout-annotated screens across all products</td><td style="text-align:left;"><strong><code>ConsoleErrors=0</code>, <code>PageErrors=0</code> (82 total)</strong></td></tr></tbody></table><h3 id="representative-verified-product-screenshots" tabindex="-1">Representative Verified Product Screenshots <a class="header-anchor" href="#representative-verified-product-screenshots" aria-label="Permalink to “Representative Verified Product Screenshots”">​</a></h3><p><img src="'+m+'" alt="SyncVerse Unified Control Dashboard" loading="lazy"></p><p><img src="'+u+'" alt="SyncBoot Enterprise Backoffice" loading="lazy"></p><p><img src="'+y+'" alt="SyncShop 8 Independent Microservices Commerce Control" loading="lazy"></p><p><img src="'+g+'" alt="SyncETA Autonomous Vision QA Control" loading="lazy"></p>',23))])}const C=i(f,[["render",h]]);export{_ as __pageData,C as default};
